@startuml

class Doctor {
  + practitionerNumber : int
  + signature : string
  + fullName : string
  + address : string
  + phoneNumber : string
}

class Patient {
  + healthNumber : string
  + firstName : string
  + lastName : string
  + dateOfBirth : date
  + address : string
  + phoneNumber : string
}

class Requisition {
  + validFrom : date
  + repetitionNumber : int
  + repetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  EVERY_HALF_YEAR
  YEARLY
}

class Test {
  + duration : int
}

class TestGroup {
  + name : string
}

class Lab {
  + address : string
  + registrationNumber : string
  + businessHoursStart : time
  + businessHoursEnd : time
  + cancellationFee : float
}

class Appointment {
  + confirmationNumber : string
  + date : date
  + startTime : time
  + endTime : time
}

class TestResult {
  + isPositive : boolean
  + report : string
}

class AppointmentType {
  + isWalkIn : boolean
  + requiresSampleDropOff : boolean
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" *-- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Test "1" -- "0..1" TestResult : has
Doctor "0..1" -- "*" TestResult : views
Patient "0..1" -- "*" TestResult : views
Requisition "1" -- "0..*" Appointment : used for
Appointment "*" -- "1" Lab : at
Appointment "*" -- "1" Test : for
Test "*" -- "1" AppointmentType : has

@enduml

